functions.utf8_string_compare:
inline int utf8_string_compare(const utf8_string_t *string, const utf8_string_t *other)
{
    size_t a_len = string->len;
    size_t b_len = other->len;
    int result = strncmp((const char *)string->data, (const char *)other->data, a_len < b_len ? a_len : b_len);
    if (result == 0)
        return a_len < b_len ? -1 : a_len > b_len ? 1 : 0;
    return result;
}

