inline int utf8_string_replace(utf8_string_t *string, size_t pos, size_t len, const utf8_string_t *replacement)
{
    int err;
    if (pos > string->len)
        return -1;
    if (pos + len > string->len)
        len = string->len - pos;
    size_t replaced_len = string->len + replacement->len - len;
    err = utf8_string_reserve(string, replaced_len);
    if (err < 0)
