functions.utf_endianness:
inline utf_endianness_t utf_endianness(void)
{
    const union {
        uint8_t u8[2];
        uint16_t u16;
    } byte_order = {{1, 0}};
    return byte_order.u16 == 1 ? utf_le : utf_be;
}

functions.latin1_convert_to_utf16le:
size_t latin1_convert_to_utf16le(const latin1_t *data, size_t len, utf16_t *result)
{
    size_t pos = 0;
    utf16_t *start = result;
    while (pos < len)
    {
        *result++ = utf_is_be() ? utf_swap_uint16(data[pos]) : data[pos];
        pos++;
    }
    return result - start;
}

