functions.latin1_convert_to_utf8:
size_t latin1_convert_to_utf8(const latin1_t *data, size_t len, utf8_t *result)
{
    size_t pos = 0;
    utf8_t *start = result;
    while (pos < len)
    {
        if (pos + 16 <= len)
        {
            uint64_t v1;
            memcpy(&v1, data + pos, sizeof(uint64_t));
            uint64_t v2;
            memcpy(&v2, data + pos + sizeof(uint64_t), sizeof(uint64_t));
            uint64_t v = v1 | v2;
            if ((v & 0x8080808080808080) == 0)
            {
                size_t final_pos = pos + 16;
                while (pos < final_pos)
                {
                    *result++ = data[pos];
                    pos++;
                }
                continue;
            }
        }
        unsigned char byte = data[pos];
        if ((byte & 0x80) == 0)
        {
            *result++ = byte;
            pos++;
        }
        else
        {
            *result++ = (byte >> 6) | 0b11000000;
            *result++ = (byte & 0b111111) | 0b10000000;
            pos++;
        }
    }
    return result - start;
}

