inline utf_endianness_t utf_endianness(void)
{
    const union {
        uint8_t u8[2];
        uint16_t u16;
    } byte_order = {{1, 0}};
    return byte_order.u16 == 1 ? utf_le : utf_be;
}

functions.utf8_length_from_utf16le:
size_t utf8_length_from_utf16le(const utf16_t *data, size_t len)
{
    size_t counter = 0;
    uint16_t word;
    for (size_t i = 0; i < len; i++)
    {
        word = utf_is_be() ? utf_swap_uint16(data[i]) : data[i];
        if (word <= 0x7f)
        {
            counter++;
        }
        else if (word <= 0x7ff)
        {
            counter += 2;
        }
        else if ((word <= 0xd7ff) || (word >= 0xe000))
        {
            counter += 3;
        }
        else
        {
            counter += 2;
        }
    }
    return counter;
}

