functions.utf_endianness:
inline utf_endianness_t utf_endianness(void)
{
    const union {
        uint8_t u8[2];
        uint16_t u16;
    } byte_order = {{1, 0}};
    return byte_order.u16 == 1 ? utf_le : utf_be;
}

functions.utf32_length_from_utf16le:
size_t utf32_length_from_utf16le(const utf16_t *data, size_t len)
{
    size_t counter = 0;
    for (size_t i = 0; i < len; i++)
    {
        uint16_t word = utf_is_be() ? utf_swap_uint16(data[i]) : data[i];
        counter += ((word & 0xfc00) != 0xdc00);
    }
    return counter;
}

