functions.utf8_string_reserve:
inline int utf8_string_reserve(utf8_string_t *string, size_t len)
{
    size_t cap = string->data == string->buf ? sizeof(string->buf) : string->cap;
    if (len <= cap)
        return 0;
    len--;
    len |= len >> 1;
    len |= len >> 2;
    len |= len >> 4;
    len |= len >> 8;
    len |= len >> 16;
    if (sizeof(len) == 8)
        len |= len >> 32;
    len++;
    cap = len;
    utf8_t *data;
    if (string->data == string->buf)
    {
        data = (utf8_t *)malloc(cap);
        memcpy(data, string->data, string->len);
    }
    else
    {
        data = (utf8_t *)realloc(string->data, cap);
    }
    if (data == ((void *)0))
        return -1;
    string->data = data;
    string->cap = cap;
    return 0;
}

functions.utf8_string_shrink_to_fit:
inline int utf8_string_shrink_to_fit(utf8_string_t *string)
{
    if (string->data == string->buf)
        return 0;
    size_t cap = string->len;
    if (cap <= sizeof(string->buf))
