functions.utf32_validate:
_Bool utf32_validate(const utf32_t *data, size_t len)
{
    uint64_t pos = 0;
    uint32_t word;
    while (pos < len)
    {
        word = data[pos];
        if (word > 0x10ffff || (word >= 0xd800 && word <= 0xdfff))
        {
            return 0;
        }
        pos++;
    }
    return 1;
}

