functions.utf32_convert_to_latin1:
size_t utf32_convert_to_latin1(const utf32_t *data, size_t len, latin1_t *result)
{
    size_t pos = 0;
    uint32_t word, overflow = 0;
    latin1_t *start = result;
    while (pos < len)
    {
        word = data[pos];
        overflow |= word;
        *result++ = word & 0xff;
        pos++;
    }
    if (overflow & 0xffffff00)
        return 0;
    return result - start;
}

