functions.utf_endianness:
inline utf_endianness_t utf_endianness(void)
{
    const union {
        uint8_t u8[2];
        uint16_t u16;
    } byte_order = {{1, 0}};
    return byte_order.u16 == 1 ? utf_le : utf_be;
}

functions.utf32_convert_to_utf16le:
size_t utf32_convert_to_utf16le(const utf32_t *data, size_t len, utf16_t *result)
{
    size_t pos = 0;
    uint32_t word;
    utf16_t *start = result;
    while (pos < len)
    {
        word = data[pos];
        if ((word & 0xffff0000) == 0)
        {
            if (word >= 0xd800 && word <= 0xdfff)
            {
                return 0;
            }
            *result++ = utf_is_be() ? utf_swap_uint16(data[pos]) : data[pos];
        }
        else
        {
            if (word > 0x10ffff)
            {
                return 0;
            }
            word -= 0x10000;
            uint16_t high_surrogate = 0xd800 + (word >> 10);
            uint16_t low_surrogate = 0xdc00 + (word & 0x3ff);
            if (utf_is_be())
            {
                high_surrogate = utf_swap_uint16(high_surrogate);
                low_surrogate = utf_swap_uint16(low_surrogate);
            }
            *result++ = high_surrogate;
            *result++ = low_surrogate;
        }
        pos++;
    }
    return result - start;
}

