functions.utf_endianness:
inline utf_endianness_t utf_endianness(void)
{
    const union {
        uint8_t u8[2];
        uint16_t u16;
    } byte_order = {{1, 0}};
    return byte_order.u16 == 1 ? utf_le : utf_be;
}

functions.utf16le_convert_to_latin1:
size_t utf16le_convert_to_latin1(const utf16_t *data, size_t len, latin1_t *result)
{
    size_t pos = 0;
    uint16_t word, overflow = 0;
    latin1_t *start = result;
    while (pos < len)
    {
        word = utf_is_be() ? utf_swap_uint16(data[pos]) : data[pos];
        overflow |= word;
        *result++ = word & 0xff;
        pos++;
    }
    if (overflow & 0xff00)
        return 0;
    return result - start;
}

